// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mockStatic;

import java.nio.file.Path;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.lwjgl.util.lmdb.LMDB;
import org.lwjgl.util.lmdb.MDBVal;
import org.mockito.MockedStatic;

class LmdbPersistentAdjacencyPromotionWorkTest {

	@TempDir
	Path directory;

	@Test
	void anEmptyInferredPlaneIsCheckedOncePerBatchAndNeverCachedAcrossBatches() throws Exception {
		AtomicInteger inferredEdgeReads = new AtomicInteger();
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setAutoGrow(false)
				.setForceSync(true)
				.setTripleDBSize(32L << 20);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			int deltas = store.getTxnManager()
					.doWith((stack, txn) -> LmdbPersistentAdjacency.openExisting(txn).deltasDbi());
			store.startTransaction();
			try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
				if (invocation.getMethod().getName().equals("mdb_get")
						&& (int) invocation.getArgument(1) == deltas) {
					MDBVal key = invocation.getArgument(2);
					if (key.mv_size() == 33 && (key.mv_data().get(0) & 0xff) >= 2) {
						inferredEdgeReads.incrementAndGet();
					}
				}
				return invocation.callRealMethod();
			})) {
				store.storeTriplesAligned(new long[] { 10, 11 }, new long[] { 20, 20 }, new long[] { 30, 31 },
						new long[] { 0, 7 }, 2, true, true, null);
			}

			// The same native transaction acquires inferred rows between aligned operations. An earlier empty-plane
			// certificate must not suppress promotion here, even if the caller's advisory hint is stale.
			store.storeTriple(12, 20, 32, 7, false);
			store.storeTriple(99, 20, 999, 9, false);
			store.storeTriplesAligned(new long[] { 12, 13 }, new long[] { 20, 20 }, new long[] { 32, 33 },
					new long[] { 7, 0 }, 2, true, false, null);
			try (RecordIterator rows = store.getTriplesForWrite(-1, -1, -1, -1, false)) {
				assertThat(rows.next()).containsExactly(99, 20, 999, 9);
				assertThat(rows.next()).isNull();
			}
			store.commit();
		}
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.getTxnManager().doWith((stack, txn) -> {
				LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn);
				for (boolean incoming : new boolean[] { false, true }) {
					try (RecordIterator rows = adjacency.scan(txn, -1, -1, -1, -1, true, incoming)) {
						Set<List<Long>> actual = new HashSet<>();
						for (long[] quad; (quad = rows.next()) != null;) {
							assertThat(actual.add(List.of(quad[0], quad[1], quad[2], quad[3]))).isTrue();
						}
						assertThat(actual).containsExactlyInAnyOrder(List.of(10L, 20L, 30L, 0L),
								List.of(11L, 20L, 31L, 7L), List.of(12L, 20L, 32L, 7L),
								List.of(13L, 20L, 33L, 0L));
					}
					assertThat(adjacency.contains(txn, 12, 20, 32, 7, false, incoming)).isFalse();
					assertThat(adjacency.contains(txn, 99, 20, 999, 9, false, incoming)).isTrue();
				}
				assertThat(adjacency.count(txn, false)).isEqualTo(1);
				return null;
			});
		}
		assertThat(inferredEdgeReads.get())
				.as("one authoritative zero total removes every per-edge inferred lookup in that batch")
				.isZero();
	}
}
